@Component("rateCard-handler")
@ProcessingGroup("rateCard-processing-group")
public class RateCardEventHandler {
	
	// core constructor
	RateCardEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRateCardEvent
     */
    @EventHandler
    public void handle( CreateRateCardEvent event) {
        entityManager.persist(new RateCard(event.getRateCardId(), event.getName(), event.getEffectiveDate(), event.getCurrency(), event.getPublisher(), event.getRates()));
    }

    /*
     * @param	event UpdateRateCardEvent
     */
    @EventHandler
    public RateCard handle( UpdateRateCardEvent event) {
    	entityManager.merge(new RateCard(event.getRateCardId(), event.getName(), event.getEffectiveDate(), event.getCurrency(), event.getPublisher(), event.getRates()));
    }
    
    /*
     * @param	event DeleteRateCardEvent
     */
    @EventHandler
    public void on( DeleteRateCardEvent event) {
    	RateCard entity = new RateCard();
   
    	// ------------------------------------------
    	// apply the RateCardId
    	// ------------------------------------------
    	entity.setRateCardId( event.getRateCardId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RateCardRepository rateCardEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RateCardEventHandler.class.getName());

}
